_ZIP_ONLY_RE = re.compile(r"^\d{5}(?:-\d{4})?$")
_PHONE_RE = re.compile(r"^\d{3}[-.\s]?\d{3}[-.\s]?\d{4}$")

_STREET_TYPES = (
    r"blvd|street|st|ave|avenue|dr|drive|rd|road|hwy|highway|way|lane|ln|"
    r"ct|court|cir|circle|pkwy|parkway|pl|place|ter|terrace|ste|suite"
)
# A wrapped address line either starts with a street-type token ("Blvd Suite 3")
# or ends with one ("Stephenson Ave"). The word boundaries matter: without them
# real creditor names such as "STATE FARM BANK" or "21ST MORTGAGE" are grabbed
# by the same rule and silently discarded.
_STREET_PREFIX_RE = re.compile(rf"^(?:{_STREET_TYPES})\b\.?", re.I)
_STREET_SUFFIX_RE = re.compile(rf"\b(?:{_STREET_TYPES})\.?$", re.I)


def is_city_state_line(line: str) -> bool:
    return bool(_CITY_STATE_RE.match((line or "").strip()))


def is_address_or_contact_line(line: str) -> bool:
    text = (line or "").strip()
    if not text:
        return True
    if is_city_state_line(text):
        return True
    if _ZIP_ONLY_RE.match(text):
        return True
    if _PHONE_RE.match(text):
        return True
    if re.match(r"^PO Box\b", text, re.I):
        return True
    if re.match(r"^P\.?\s*O\.?\s*Box", text, re.I):
        return True
    if re.match(r"^\d+\s+\w", text):  # street address
        return True
    if _STREET_PREFIX_RE.match(text) or _STREET_SUFFIX_RE.search(text):
        return True
    return False

